struct Evens {
    n: u32,
}

impl Iterator for Evens {
    type Item = u32;

    fn next(&mut self) -> Option<u32> {
        if self.n >= 6 {
            None
        } else {
            self.n += 2;
            Some(self.n)
        }
    }
}

fn main() {
    let e = Evens { n: 0 };
    for x in e {
        println!("{x}");
    }
}

use std::fmt;

trait Loud: fmt::Display {
    fn shout(&self) -> String {
        format!("{}!", self)
    }
}

struct Name(String);

impl fmt::Display for Name {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl Loud for Name {}

fn main() {
    println!("{}", Name(String::from("hey")).shout());
}

use std::fmt::Display;

trait Describe: Display {
    fn describe(&self) -> String {
        format!("<<{}>>", self)
    }
}

struct Tag;

impl Describe for Tag {}

fn main() {
    println!("{}", Tag.describe());
}

trait Pilot {
    fn fly(&self) -> String;
}

struct Human;

impl Pilot for Human {
    fn fly(&self) -> String {
        String::from("trait")
    }
}

impl Human {
    fn fly(&self) -> String {
        String::from("own")
    }
}

fn main() {
    let h = Human;
    println!("{} {}", h.fly(), Pilot::fly(&h));
}

use std::ops::Add;

struct Meters(f64);
struct Feet(f64);

impl Add<Feet> for Meters {
    type Output = Meters;

    fn add(self, other: Feet) -> Meters {
        Meters(self.0 + other.0 * 0.5)
    }
}

fn main() {
    let total = Meters(1.0) + Feet(4.0);
    println!("{}", total.0);
}

use std::fmt;

trait Item {
    type Price;
    fn price(&self) -> Self::Price;
}

struct Pen;
struct Book;

impl Item for Pen {
    type Price = u32;
    fn price(&self) -> u32 {
        10
    }
}

impl Item for Book {
    type Price = f64;
    fn price(&self) -> f64 {
        49.5
    }
}

fn show<T: Item>(x: &T) -> String
where
    T::Price: fmt::Display,
{
    format!("price={}", x.price())
}

fn main() {
    println!("{} {}", show(&Pen), show(&Book));
}
